// Deterministic scoring. The LLM only reported coverage; all arithmetic happens here.
const src = $('When called by the bot').first().json;
const raw = $input.first().json;
const parsed = (raw && raw.output) ? raw.output : raw;

let keyPoints = [];
try {
  keyPoints = typeof src.key_points === 'string' ? JSON.parse(src.key_points) : (src.key_points || []);
} catch (e) {
  keyPoints = [];
}

const total = Array.isArray(keyPoints) ? keyPoints.length : 0;
const coveredRaw = (parsed && Array.isArray(parsed.covered)) ? parsed.covered : null;
const evidenceRaw = (parsed && Array.isArray(parsed.evidence)) ? parsed.evidence : [];
const feedback = (parsed && typeof parsed.feedback === 'string') ? parsed.feedback : '';

// Validation: the model must return one verdict per key point, no more, no fewer.
const valid = total > 0 && coveredRaw !== null && coveredRaw.length === total;

if (!valid) {
  return [{
    json: {
      grade_valid: false,
      chat_id: src.chat_id,
      question_id: src.question_id,
      topic: src.topic,
      answer: src.answer,
      input_mode: src.input_mode || 'text',
      reason: total === 0 ? 'question has no key points' : 'model returned a mismatched verdict list'
    }
  }];
}

function normalise(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9\u00e0-\u00ff ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const answerNorm = normalise(src.answer);
const answerTokens = {};
answerNorm.split(' ').forEach(function (t) { if (t) { answerTokens[t] = true; } });

// A covered verdict only counts if its evidence quote really came from the answer.
// Models will otherwise echo the rubric back as evidence, which inflates the score.
function evidenceHolds(quote) {
  const q = normalise(quote);
  if (q.length < 8) { return false; }
  if (answerNorm.indexOf(q) !== -1) { return true; }

  // Allow for a dropped or altered word in an otherwise genuine quote.
  const words = q.split(' ').filter(function (w) { return w.length > 2; });
  if (words.length === 0) { return false; }
  let hits = 0;
  words.forEach(function (w) { if (answerTokens[w]) { hits += 1; } });
  return (hits / words.length) >= 0.8;
}

const claimed = coveredRaw.map(function (v) { return v === true || v === 'true'; });
const covered = [];
const rejected = [];

for (let i = 0; i < total; i++) {
  if (!claimed[i]) {
    covered.push(false);
  } else if (evidenceHolds(evidenceRaw[i])) {
    covered.push(true);
  } else {
    // Claimed as covered but the quote is not in the answer, so it does not count.
    covered.push(false);
    rejected.push(keyPoints[i]);
  }
}

const hits = covered.filter(Boolean).length;
const claimedHits = claimed.filter(Boolean).length;

const met = [];
const missed = [];
for (let i = 0; i < total; i++) {
  if (covered[i]) {
    met.push(keyPoints[i]);
  } else {
    missed.push(keyPoints[i]);
  }
}

// Coverage is worth 4. Structure is worth up to 1. Hints cost 0.5 each, capped at 1.
const words = String(src.answer || '').trim().split(/\s+/).filter(Boolean).length;
let structureBonus = 0;
if (words >= 60) { structureBonus = 0.5; }
if (words >= 120) { structureBonus = 1; }

const hints = Number(src.hints_used || 0);
const hintPenalty = Math.min(1, hints * 0.5);

const rawScore = (hits / total) * 4 + structureBonus - hintPenalty;
const score = Math.round(Math.max(0, Math.min(5, rawScore)) * 2) / 2;

// Spaced repetition: a weak answer comes back in 2 days, a middling one in a week.
const now = new Date();
let dueAt = null;
if (score < 3) {
  dueAt = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString();
} else if (score < 4) {
  dueAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();
}

let missedBlock = 'Nothing major missing.';
if (missed.length > 0) {
  missedBlock = missed.map(function (m) { return '- ' + m; }).join('\n');
}

let metBlock = 'None of the checklist points came through.';
if (met.length > 0) {
  metBlock = met.map(function (m) { return '- ' + m; }).join('\n');
}

return [{
  json: {
    grade_valid: true,
    chat_id: src.chat_id,
    question_id: src.question_id,
    topic: src.topic,
    answer: src.answer,
    input_mode: src.input_mode || 'text',
    score: score,
    hits: hits,
    claimed_hits: claimedHits,
    rejected_count: rejected.length,
    total: total,
    words: words,
    structure_bonus: structureBonus,
    hint_penalty: hintPenalty,
    covered_json: JSON.stringify({ covered: covered, claimed: claimed, evidence: evidenceRaw, rejected: rejected, key_points: keyPoints }),
    feedback: feedback,
    met_block: metBlock,
    missed_block: missedBlock,
    created_at: now.toISOString(),
    due_at: dueAt
  }
}];
